//! Daemon configuration: /etc/fp6-updated/config.json, generated by the
//! NixOS module (the laptop dry run passes its own with --config).

use serde::{Deserialize, Serialize};
use std::path::PathBuf;

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase", default)]
pub struct Config {
    /// The only non-root caller accepted (the phone user).
    pub uid: u32,
    pub polkit_action: Option<String>,
    pub session_bus: bool,
    pub device: String,
    pub channel: String,
    /// Update server root (manifest at <server>/channels/<channel>/manifest.json).
    pub server: Option<String>,
    /// Overrides the cache named in the manifest.
    pub cache_url: Option<String>,
    /// minisign public key (base64 line) trusted for manifests.
    pub manifest_public_key: String,
    /// Nix signing key name:base64 (informational; enforced by nix.conf).
    pub nix_public_key: String,
    /// A/B install with slot switch and automatic rollback. Default false:
    /// the running slot's boot partition is rewritten (single-slot mode).
    pub allow_slot_switch: bool,
    /// Boots of a new slot that may fail the health check before rollback.
    pub max_boot_attempts: u32,
    /// A/B pairs that may differ between slots (only after the supervised
    /// analysis; see the README). Default: none.
    pub allowed_slot_differences: Vec<String>,
    pub boot_partition_size: u64,
    pub booted_release: PathBuf,
    pub current_release: PathBuf,
    pub booted_system: PathBuf,
    pub by_partlabel: PathBuf,
    pub proc_cmdline: PathBuf,
    pub state_dir: PathBuf,
    pub backup_dir: PathBuf,
    /// Full-partition backups kept (each 96 MiB).
    pub keep_backups: usize,
    pub profiles: PathBuf,
    pub profile: String,
    pub gcroots: PathBuf,
    /// Real store directory, for "is this path here yet" (progress).
    pub store_dir: PathBuf,
    /// `--store` argument for nix commands (the laptop dry run's local store).
    pub nix_store: Option<String>,
    pub nix: String,
    pub nix_env: String,
    pub qbootctl: String,
    pub systemctl: String,
    pub saver_file: PathBuf,
    pub power_supply: PathBuf,
    /// Laptop dry run: conditions/health facts from JSON files, boot
    /// partitions may be regular files, reboots are only logged, slot
    /// control is a JSON file.
    pub fake: Option<Fake>,
    pub critical_units: Vec<String>,
    pub shell_processes: Vec<String>,
    pub ssh_port: u16,
    pub netbird_unit: Option<String>,
    pub netbird_interface: String,
    /// Health check: how long to wait for the session, then the stability wait.
    pub health_timeout: u64,
    pub health_stable: u64,
    pub idle_exit: i64,
}

#[derive(Serialize, Deserialize, Clone, Debug, Default)]
#[serde(rename_all = "camelCase", default)]
pub struct Fake {
    pub conditions: Option<PathBuf>,
    pub health_facts: Option<PathBuf>,
    pub slots: Option<PathBuf>,
    pub reboot_log: Option<PathBuf>,
    /// File holding the local hour (0-23) the night window sees.
    pub hour_file: Option<PathBuf>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            uid: 10000,
            polkit_action: Some("com.fairphone6.update.manage".into()),
            session_bus: false,
            device: "fairphone-fp6".into(),
            channel: "kernel6".into(),
            server: None,
            cache_url: None,
            manifest_public_key: String::new(),
            nix_public_key: String::new(),
            allow_slot_switch: false,
            max_boot_attempts: 2,
            allowed_slot_differences: vec![],
            boot_partition_size: 100_663_296,
            booted_release: "/run/booted-system/etc/fp6-release".into(),
            current_release: "/run/current-system/etc/fp6-release".into(),
            booted_system: "/run/booted-system".into(),
            by_partlabel: "/dev/disk/by-partlabel".into(),
            proc_cmdline: "/proc/cmdline".into(),
            state_dir: "/var/lib/fp6-updated".into(),
            backup_dir: "/var/lib/fp6-updated/backups".into(),
            keep_backups: 2,
            profiles: "/nix/var/nix/profiles".into(),
            profile: "system".into(),
            gcroots: "/nix/var/nix/gcroots/fp6-ota".into(),
            store_dir: "/nix/store".into(),
            nix_store: None,
            nix: "nix".into(),
            nix_env: "nix-env".into(),
            qbootctl: "qbootctl".into(),
            systemctl: "systemctl".into(),
            saver_file: "/run/fp6-battery/saver".into(),
            power_supply: "/sys/class/power_supply".into(),
            fake: None,
            critical_units: ["display-manager.service", "dbus.service", "systemd-logind.service", "NetworkManager.service", "sshd.service"]
                .map(String::from).to_vec(),
            shell_processes: ["lomiri", ".lomiri-wrapped"].map(String::from).to_vec(),
            ssh_port: 22,
            netbird_unit: None,
            netbird_interface: "wt0".into(),
            health_timeout: 300,
            health_stable: 30,
            idle_exit: 120,
        }
    }
}

impl Config {
    pub fn load(path: &std::path::Path) -> Result<Config, String> {
        let b = std::fs::read(path).map_err(|e| format!("{}: {e}", path.display()))?;
        serde_json::from_slice(&b).map_err(|e| format!("{}: {e}", path.display()))
    }

    pub fn manifest_url(&self, server: &str) -> String {
        format!("{}/channels/{}/manifest.json", server.trim_end_matches('/'), self.channel)
    }

    /// See url.rs: https anywhere, http only to private/NetBird/local IP
    /// literals, file:// only on the dry run's fake phone.
    pub fn url_allowed(&self, url: &str) -> bool {
        crate::url::check(url, self.fake.is_some()).is_ok()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn defaults_and_urls() {
        let c: Config = serde_json::from_str(r#"{"channel":"k6","allowSlotSwitch":false}"#).unwrap();
        assert_eq!(c.uid, 10000);
        assert!(!c.allow_slot_switch);
        // a NetBird (CGNAT) address, built so no literal address is in the source
        let nb = format!("http://{}.64.0.10:8742", 100);
        assert_eq!(c.manifest_url(&format!("{nb}/")), format!("{nb}/channels/k6/manifest.json"));
        assert!(c.url_allowed(&format!("{nb}/x")));
        assert!(c.url_allowed("https://example.org/x"));
        assert!(!c.url_allowed("http://example.org/x"));
        assert!(!c.url_allowed("ftp://x"));
        assert!(!c.url_allowed("file:///srv/ota/x"), "file:// only on the fake phone");
    }
}
